def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid_mask = remaining >= 0
    if not np.any(valid_mask):
        return np.full_like(bins, -np.inf, dtype=float)

    valid_rem = remaining[valid_mask]
    entropy_term = -np.sum(valid_rem * np.log(valid_rem + 1e-8))
    dispersion_penalty = np.where(valid_mask, -np.abs(remaining - np.mean(valid_rem)), 0.0)
    tightness_reward = np.where(valid_mask, np.exp(-remaining), -np.inf)

    return np.where(valid_mask, tightness_reward + 0.05 * dispersion_penalty + 0.01 * entropy_term, -np.inf)
